window.receiveProjectSource({"path": "test/integration/ingest_ledger/test_triggers.py", "lines": ["\"\"\"Immutability, sealing, scope-binding and absorbed-duplicate rules, by direct SQL.", "", "The triggers are ERD IngestLedger-version-1.06's, copied verbatim. They raise", "one message per group of guarded columns, so each case asserts its group's", "message fires and the change is refused. These run as the migrating superuser:", "triggers and constraints fire for every role, so a guard that holds here holds", "for the runtime roles too.", "\"\"\"", "", "import uuid", "from datetime import timedelta", "from typing import Any", "", "import pytest", "from sqlalchemy import Column, text, update", "from sqlalchemy.dialects.postgresql import ENUM", "from sqlalchemy.exc import DBAPIError, IntegrityError", "from sqlalchemy.ext.asyncio import AsyncSession", "", "from db.ingest_ledger.ddl.triggers import APPEND_ONLY_TABLES", "from test.integration.ingest_ledger import rows as r", "from test.integration.ingest_ledger.rows import Parents", "", "pytestmark = [pytest.mark.integration, pytest.mark.ci_db]", "", "OPERATION_ID = uuid.UUID(\"00000000-0000-4000-8000-000000000042\")", "", "# The first delivery_units group; v1.05 adds source system and unit natural key kind.", "WRITE_ONCE_MESSAGE = (", "    \"client_id, source system, unit natural key kind, payload handling and the \"", "    \"admission-resolved latency class are write-once\"", ")", "", "# (table, column, kind, group message) for every column guard in the ERD (v1.06).", "# set_once: NULL -> value allowed once, then fixed. immutable: any change refused.", "GUARDS: list[tuple[str, str, str, str]] = [", "    (", "        \"delivery_units\",", "        \"client_id\",", "        \"immutable\",", "        WRITE_ONCE_MESSAGE,", "    ),", "    (\"delivery_units\", \"source_system_id\", \"immutable\", WRITE_ONCE_MESSAGE),", "    (\"delivery_units\", \"unit_natural_key_kind\", \"immutable\", WRITE_ONCE_MESSAGE),", "    (", "        \"delivery_units\",", "        \"payload_arrival_mode\",", "        \"immutable\",", "        WRITE_ONCE_MESSAGE,", "    ),", "    (", "        \"delivery_units\",", "        \"payload_disposition\",", "        \"immutable\",", "        WRITE_ONCE_MESSAGE,", "    ),", "    (", "        \"delivery_units\",", "        \"resolved_latency_class\",", "        \"immutable\",", "        WRITE_ONCE_MESSAGE,", "    ),", "    (\"delivery_units\", \"scope_kind\", \"set_once\", \"scope identity is set-once\"),", "    (\"delivery_units\", \"operation_id\", \"set_once\", \"scope identity is set-once\"),", "    (\"delivery_units\", \"scope_bound_at\", \"set_once\", \"scope identity is set-once\"),", "    (\"delivery_units\", \"landed_at\", \"set_once\", \"landing and binding facts are set-once\"),", "    (", "        \"delivery_units\",", "        \"source_dataset_binding_id\",", "        \"set_once\",", "        \"landing and binding facts are set-once\",", "    ),", "    (", "        \"delivery_units\",", "        \"source_dataset_binding_version\",", "        \"set_once\",", "        \"landing and binding facts are set-once\",", "    ),", "    (\"delivery_units\", \"dataset_id\", \"set_once\", \"landing and binding facts are set-once\"),", "    (", "        \"delivery_units\",", "        \"dataset_catalog_version\",", "        \"set_once\",", "        \"landing and binding facts are set-once\",", "    ),", "    (\"delivery_units\", \"source_policy_id\", \"set_once\", \"landing and binding facts are set-once\"),", "    (", "        \"delivery_units\",", "        \"source_policy_version\",", "        \"set_once\",", "        \"landing and binding facts are set-once\",", "    ),", "    (", "        \"delivery_units\",", "        \"source_policy_digest\",", "        \"set_once\",", "        \"landing and binding facts are set-once\",", "    ),", "    (", "        \"delivery_units\",", "        \"intake_authorization_snapshot_id\",", "        \"set_once\",", "        \"landing and binding facts are set-once\",", "    ),", "    (", "        \"delivery_units\",", "        \"intake_authorization_snapshot_digest\",", "        \"set_once\",", "        \"landing and binding facts are set-once\",", "    ),", "    (\"delivery_units\", \"unit_natural_key\", \"set_once\", \"landing and binding facts are set-once\"),", "    (\"delivery_units\", \"received_at\", \"set_once\", \"landing and binding facts are set-once\"),", "    (\"delivery_units\", \"created_at\", \"set_once\", \"landing and binding facts are set-once\"),", "    (", "        \"evidence_acquisition_work\",", "        \"client_id\",", "        \"immutable\",", "        \"intent binding and scope are write-once\",", "    ),", "    (", "        \"evidence_acquisition_work\",", "        \"acquisition_intent_id\",", "        \"immutable\",", "        \"intent binding and scope are write-once\",", "    ),", "    (", "        \"evidence_acquisition_work\",", "        \"scope_kind\",", "        \"immutable\",", "        \"intent binding and scope are write-once\",", "    ),", "    (", "        \"evidence_acquisition_work\",", "        \"operation_id\",", "        \"immutable\",", "        \"intent binding and scope are write-once\",", "    ),", "    (", "        \"evidence_acquisition_work\",", "        \"created_at\",", "        \"immutable\",", "        \"intent binding and scope are write-once\",", "    ),", "    (", "        \"ledger_outbox_entries\",", "        \"client_id\",", "        \"immutable\",", "        \"publication identity, body, causality and scope are immutable\",", "    ),", "    (", "        \"ledger_outbox_entries\",", "        \"source_system_id\",", "        \"immutable\",", "        \"publication identity, body, causality and scope are immutable\",", "    ),", "    (", "        \"ledger_outbox_entries\",", "        \"delivery_unit_id\",", "        \"immutable\",", "        \"publication identity, body, causality and scope are immutable\",", "    ),", "    (", "        \"ledger_outbox_entries\",", "        \"sub_unit_manifest_id\",", "        \"immutable\",", "        \"publication identity, body, causality and scope are immutable\",", "    ),", "    (", "        \"ledger_outbox_entries\",", "        \"scope_kind\",", "        \"immutable\",", "        \"publication identity, body, causality and scope are immutable\",", "    ),", "    (", "        \"ledger_outbox_entries\",", "        \"operation_id\",", "        \"immutable\",", "        \"publication identity, body, causality and scope are immutable\",", "    ),", "    (", "        \"ledger_outbox_entries\",", "        \"publication_kind\",", "        \"immutable\",", "        \"publication identity, body, causality and scope are immutable\",", "    ),", "    (", "        \"ledger_outbox_entries\",", "        \"causal_publication_id\",", "        \"immutable\",", "        \"publication identity, body, causality and scope are immutable\",", "    ),", "    (", "        \"ledger_outbox_entries\",", "        \"destruction_epochs\",", "        \"immutable\",", "        \"publication identity, body, causality and scope are immutable\",", "    ),", "    (", "        \"ledger_outbox_entries\",", "        \"destination\",", "        \"immutable\",", "        \"publication identity, body, causality and scope are immutable\",", "    ),", "    (", "        \"ledger_outbox_entries\",", "        \"target_work_run_id\",", "        \"immutable\",", "        \"publication identity, body, causality and scope are immutable\",", "    ),", "    (", "        \"ledger_outbox_entries\",", "        \"target_artifact_id\",", "        \"immutable\",", "        \"publication identity, body, causality and scope are immutable\",", "    ),", "    (", "        \"ledger_outbox_entries\",", "        \"target_artifact_version\",", "        \"immutable\",", "        \"publication identity, body, causality and scope are immutable\",", "    ),", "    (", "        \"ledger_outbox_entries\",", "        \"target_ess_operation_id\",", "        \"immutable\",", "        \"publication identity, body, causality and scope are immutable\",", "    ),", "    (", "        \"ledger_outbox_entries\",", "        \"payload\",", "        \"immutable\",", "        \"publication identity, body, causality and scope are immutable\",", "    ),", "    (", "        \"ledger_outbox_entries\",", "        \"dedupe_key\",", "        \"immutable\",", "        \"publication identity, body, causality and scope are immutable\",", "    ),", "    (", "        \"ledger_outbox_entries\",", "        \"created_at\",", "        \"immutable\",", "        \"publication identity, body, causality and scope are immutable\",", "    ),", "    (", "        \"reconciliation_findings\",", "        \"client_id\",", "        \"immutable\",", "        \"finding identity, subject address and scope are write-once\",", "    ),", "    (", "        \"reconciliation_findings\",", "        \"scope_kind\",", "        \"immutable\",", "        \"finding identity, subject address and scope are write-once\",", "    ),", "    (", "        \"reconciliation_findings\",", "        \"operation_id\",", "        \"immutable\",", "        \"finding identity, subject address and scope are write-once\",", "    ),", "    (", "        \"reconciliation_findings\",", "        \"finding_class\",", "        \"immutable\",", "        \"finding identity, subject address and scope are write-once\",", "    ),", "    (", "        \"reconciliation_findings\",", "        \"subject_kind\",", "        \"immutable\",", "        \"finding identity, subject address and scope are write-once\",", "    ),", "    (", "        \"reconciliation_findings\",", "        \"subject_id\",", "        \"immutable\",", "        \"finding identity, subject address and scope are write-once\",", "    ),", "    (", "        \"reconciliation_findings\",", "        \"subject_bucket\",", "        \"immutable\",", "        \"finding identity, subject address and scope are write-once\",", "    ),", "    (", "        \"reconciliation_findings\",", "        \"subject_key\",", "        \"immutable\",", "        \"finding identity, subject address and scope are write-once\",", "    ),", "    (", "        \"reconciliation_findings\",", "        \"subject_object_version_id\",", "        \"immutable\",", "        \"finding identity, subject address and scope are write-once\",", "    ),", "    (", "        \"reconciliation_findings\",", "        \"subject_fingerprint\",", "        \"immutable\",", "        \"finding identity, subject address and scope are write-once\",", "    ),", "    (", "        \"reconciliation_findings\",", "        \"detected_at\",", "        \"immutable\",", "        \"finding identity, subject address and scope are write-once\",", "    ),", "    (", "        \"reconciliation_findings\",", "        \"created_at\",", "        \"immutable\",", "        \"finding identity, subject address and scope are write-once\",", "    ),", "    (\"source_item_claims\", \"client_id\", \"immutable\", \"scope is write-once\"),", "    (\"source_item_claims\", \"scope_kind\", \"immutable\", \"scope is write-once\"),", "    (\"source_item_claims\", \"operation_id\", \"immutable\", \"scope is write-once\"),", "    (", "        \"source_item_claims\",", "        \"source_record_lineage_id\",", "        \"set_once\",", "        \"lineage binding and canonical publication facts are set-once\",", "    ),", "    (", "        \"source_item_claims\",", "        \"owning_delivery_unit_id\",", "        \"set_once\",", "        \"lineage binding and canonical publication facts are set-once\",", "    ),", "    (", "        \"source_item_claims\",", "        \"dataset_id\",", "        \"set_once\",", "        \"lineage binding and canonical publication facts are set-once\",", "    ),", "    (", "        \"source_item_claims\",", "        \"canonical_persisted_at\",", "        \"set_once\",", "        \"lineage binding and canonical publication facts are set-once\",", "    ),", "    (", "        \"source_item_claims\",", "        \"canonical_base_artifact_id\",", "        \"set_once\",", "        \"lineage binding and canonical publication facts are set-once\",", "    ),", "    (", "        \"source_item_claims\",", "        \"canonical_base_artifact_version\",", "        \"set_once\",", "        \"lineage binding and canonical publication facts are set-once\",", "    ),", "    (", "        \"source_item_claims\",", "        \"canonical_bundle_digest\",", "        \"set_once\",", "        \"lineage binding and canonical publication facts are set-once\",", "    ),", "    (", "        \"source_item_claims\",", "        \"claimed_at\",", "        \"set_once\",", "        \"lineage binding and canonical publication facts are set-once\",", "    ),", "    (", "        \"source_item_claims\",", "        \"created_at\",", "        \"set_once\",", "        \"lineage binding and canonical publication facts are set-once\",", "    ),", "    (\"source_record_lineages\", \"dataset_id\", \"immutable\", \"lineage identity is write-once\"),", "    (\"source_record_lineages\", \"source_system_id\", \"immutable\", \"lineage identity is write-once\"),", "    (\"source_record_lineages\", \"source_record_id\", \"immutable\", \"lineage identity is write-once\"),", "    (\"source_record_lineages\", \"client_id\", \"immutable\", \"lineage identity is write-once\"),", "    (\"source_record_lineages\", \"scope_kind\", \"immutable\", \"lineage identity is write-once\"),", "    (\"source_record_lineages\", \"operation_id\", \"immutable\", \"lineage identity is write-once\"),", "    (\"source_record_lineages\", \"created_at\", \"immutable\", \"lineage identity is write-once\"),", "    (", "        \"source_systems\",", "        \"source_system_key\",", "        \"immutable\",", "        \"source system identity and registration are write-once\",", "    ),", "    (", "        \"source_systems\",", "        \"client_id\",", "        \"immutable\",", "        \"source system identity and registration are write-once\",", "    ),", "    (", "        \"source_systems\",", "        \"registered_at\",", "        \"immutable\",", "        \"source system identity and registration are write-once\",", "    ),", "    (", "        \"source_systems\",", "        \"created_at\",", "        \"immutable\",", "        \"source system identity and registration are write-once\",", "    ),", "    (\"sub_unit_manifests\", \"client_id\", \"immutable\", \"scope is write-once\"),", "    (\"sub_unit_manifests\", \"scope_kind\", \"immutable\", \"scope is write-once\"),", "    (\"sub_unit_manifests\", \"operation_id\", \"immutable\", \"scope is write-once\"),", "    (\"sub_unit_manifests\", \"terminal_at\", \"set_once\", \"identity and planning facts are set-once\"),", "    (", "        \"sub_unit_manifests\",", "        \"delivery_unit_id\",", "        \"set_once\",", "        \"identity and planning facts are set-once\",", "    ),", "    (\"sub_unit_manifests\", \"subkey\", \"set_once\", \"identity and planning facts are set-once\"),", "    (\"sub_unit_manifests\", \"subkey_kind\", \"set_once\", \"identity and planning facts are set-once\"),", "    (\"sub_unit_manifests\", \"generation\", \"set_once\", \"identity and planning facts are set-once\"),", "    (\"sub_unit_manifests\", \"run_id\", \"set_once\", \"identity and planning facts are set-once\"),", "    (\"sub_unit_manifests\", \"planned_at\", \"set_once\", \"identity and planning facts are set-once\"),", "    (\"sub_unit_manifests\", \"created_at\", \"set_once\", \"identity and planning facts are set-once\"),", "]", "", "# Rows where every set-once column of the table is non-null, so the guard is", "# exercised against a value that is already set.", "RICH: dict[str, Any] = {", "    \"delivery_units\": lambda p: r.delivery_unit_row(", "        p.client_id,", "        p.source_system_id,", "        scope_kind=\"OPERATION\",", "        operation_id=OPERATION_ID,", "        external_namespace=\"ns\",", "        external_operation_key=f\"op-{uuid.uuid4().hex[:8]}\",", "        scope_bound_at=r.NOW,", "        state=\"LANDED\",", "        landed_at=r.NOW,", "        **r.QUARANTINE_OBJECT,", "    ),", "    \"source_record_lineages\": lambda p: r.lineage_row(p),", "    \"ledger_outbox_entries\": lambda p: r.outbox_row(p),", "    \"source_item_claims\": lambda p: r.claim_row(", "        p,", "        **r.PREPARED_CLAIM,", "        canonical_persisted_at=r.NOW,", "        canonical_base_artifact_id=r.new_id(),", "        canonical_base_artifact_version=1,", "        canonical_bundle_digest=\"sha256:bundle\",", "    ),", "    \"sub_unit_manifests\": lambda p: r.manifest_row(", "        p, run_id=r.new_id(), outcome=\"SKIPPED\", outcome_reason=\"none\", terminal_at=r.NOW", "    ),", "    \"source_systems\": lambda p: r.source_system_row(p.client_id),", "    \"reconciliation_findings\": lambda p: r.finding_row(p),", "    \"evidence_acquisition_work\": lambda p: r.work_row(p),", "}", "", "", "def _different_value(column: Column, current: Any) -> Any:", "    \"\"\"Return a value of the column's type that differs from ``current``.\"\"\"", "    if isinstance(column.type, ENUM):", "        return next(v for v in column.type.enums if v != current)", "    python_type = column.type.python_type", "    if python_type is uuid.UUID:", "        return uuid.uuid4()", "    if python_type is int:", "        return (current or 0) + 7", "    if python_type is str:", "        return f\"{current}-changed\"", "    if python_type.__name__ == \"datetime\":", "        return (current or r.NOW) + timedelta(days=1)", "    if python_type in (dict, list):", "        return [{\"changed\": True}]", "    raise AssertionError(f\"no change value for {column}\")", "", "", "async def _refused(", "    ledger: AsyncSession, table_name: str, row_id: Any, values: dict[str, Any]", ") -> Any:", "    \"\"\"Apply an update expected to be refused and return the database error.\"\"\"", "    table = r.table(table_name)", "    with pytest.raises(DBAPIError) as exc_info:", "        async with ledger.begin_nested():", "            await ledger.execute(update(table).where(table.c.id == row_id).values(**values))", "    return r.pg_error(exc_info.value)", "", "", "async def _current(ledger: AsyncSession, table_name: str, row_id: Any, column: str) -> Any:", "    table = r.table(table_name)", "    return (", "        await ledger.execute(", "            table.select().with_only_columns(table.c[column]).where(table.c.id == row_id)", "        )", "    ).scalar_one()", "", "", "@pytest.mark.parametrize(", "    (\"table_name\", \"column\", \"kind\", \"message\"),", "    GUARDS,", "    ids=[f\"{t}.{c}\" for t, c, _, _ in GUARDS],", ")", "async def test_guarded_column_cannot_change(", "    ledger: AsyncSession, parents: Parents, table_name: str, column: str, kind: str, message: str", ") -> None:", "    \"\"\"Changing a set-once value, or any immutable value, is refused by its group's guard.\"\"\"", "    row = RICH[table_name](parents)", "    if table_name == \"evidence_acquisition_work\":", "        intent = r.intent_row(parents)", "        await r.insert_row(ledger, \"evidence_acquisition_intents\", intent)", "        row[\"acquisition_intent_id\"] = intent[\"id\"]", "    await r.insert_row(ledger, table_name, row)", "    current = await _current(ledger, table_name, row[\"id\"], column)", "    if kind == \"set_once\":", "        assert current is not None, f\"rich {table_name} row must set {column}\"", "    error = await _refused(", "        ledger,", "        table_name,", "        row[\"id\"],", "        {column: _different_value(r.table(table_name).c[column], current)},", "    )", "    assert message in str(error), error", "", "", "def test_guard_specification_covers_the_ticket_rules() -> None:", "    \"\"\"The write-once columns named by DAT-8325 and its review are all guarded.\"\"\"", "    guarded = {(t, c) for t, c, _, _ in GUARDS}", "    required = {", "        (\"delivery_units\", \"landed_at\"),", "        (\"delivery_units\", \"payload_disposition\"),", "        (\"delivery_units\", \"payload_arrival_mode\"),", "        (\"delivery_units\", \"scope_bound_at\"),", "        (\"delivery_units\", \"resolved_latency_class\"),", "        (\"delivery_units\", \"source_system_id\"),", "        (\"delivery_units\", \"unit_natural_key_kind\"),", "        (\"delivery_units\", \"dataset_id\"),", "        (\"delivery_units\", \"source_dataset_binding_id\"),", "        (\"source_systems\", \"source_system_key\"),", "        (\"source_record_lineages\", \"dataset_id\"),", "        (\"sub_unit_manifests\", \"terminal_at\"),", "        *(", "            (t, \"operation_id\")", "            for t in (", "                \"delivery_units\",", "                \"source_record_lineages\",", "                \"source_item_claims\",", "                \"sub_unit_manifests\",", "                \"ledger_outbox_entries\",", "                \"reconciliation_findings\",", "                \"evidence_acquisition_work\",", "            )", "        ),", "    }", "    assert required <= guarded, sorted(required - guarded)", "", "", "async def test_unguarded_update_still_succeeds(ledger: AsyncSession, parents: Parents) -> None:", "    \"\"\"A normal state change on a scoped delivery works (the ERD scope_key bug rejected it).\"\"\"", "    table = r.table(\"delivery_units\")", "    await ledger.execute(", "        update(table)", "        .where(table.c.id == parents.delivery_unit_id)", "        .values(state=\"LANDED\", landed_at=r.NOW, **r.QUARANTINE_OBJECT)", "    )", "    state = (", "        await ledger.execute(", "            text(", "                \"SELECT state, updated_at IS NOT NULL FROM ingest_ledger.delivery_units WHERE id = :i\"", "            ),", "            {\"i\": parents.delivery_unit_id},", "        )", "    ).one()", "    assert tuple(state) == (\"LANDED\", True)", "", "", "async def test_effective_latency_classes_stay_mutable(", "    ledger: AsyncSession, parents: Parents", ") -> None:", "    \"\"\"Escalation lands on the work and manifest rows, never on the admitted receipt.\"\"\"", "    intent = r.intent_row(parents)", "    await r.insert_row(ledger, \"evidence_acquisition_intents\", intent)", "    work = r.work_row(parents, acquisition_intent_id=intent[\"id\"])", "    await r.insert_row(ledger, \"evidence_acquisition_work\", work)", "    for table_name, row_id in (", "        (\"evidence_acquisition_work\", work[\"id\"]),", "        (\"sub_unit_manifests\", parents.manifest_id),", "    ):", "        table = r.table(table_name)", "        await ledger.execute(", "            update(table).where(table.c.id == row_id).values(effective_latency_class=\"EMERGENT\")", "        )", "", "", "# ------------------------------------------------------------------ append-only", "", "", "def _append_only_row(parents: Parents, table_name: str) -> dict[str, Any] | None:", "    builders = {", "        \"scan_verdicts\": r.scan_verdict_row,", "        \"operator_dispositions\": r.disposition_row,", "        \"destruction_receipts\": r.destruction_receipt_row,", "        \"evidence_acquisition_intents\": r.intent_row,", "        \"capability_bindings\": r.capability_binding_row,", "    }", "    build = builders.get(table_name)", "    return build(parents) if build else None", "", "", "@pytest.mark.parametrize(\"table_name\", APPEND_ONLY_TABLES)", "@pytest.mark.parametrize(\"operation\", [\"UPDATE\", \"DELETE\"])", "async def test_append_only_tables_reject_update_and_delete(", "    ledger: AsyncSession, parents: Parents, table_name: str, operation: str", ") -> None:", "    \"\"\"History tables accept inserts only, for every role.\"\"\"", "    row = _append_only_row(parents, table_name)", "    if row is None:", "        row_id = parents.result_id", "    else:", "        await r.insert_row(ledger, table_name, row)", "        row_id = row[\"id\"]", "    sql = (", "        f\"UPDATE ingest_ledger.{table_name} SET client_id = client_id WHERE id = :i\"", "        if operation == \"UPDATE\"", "        else f\"DELETE FROM ingest_ledger.{table_name} WHERE id = :i\"", "    )", "    with pytest.raises(DBAPIError) as exc_info:", "        async with ledger.begin_nested():", "            await ledger.execute(text(sql), {\"i\": row_id})", "    error = str(r.pg_error(exc_info.value))", "    assert f\"ingest_ledger.{table_name} is append-only\" in error", "    assert operation in error", "", "", "def test_append_only_set_is_the_six_named_tables() -> None:", "    assert set(APPEND_ONLY_TABLES) == {", "        \"scan_verdicts\",", "        \"operator_dispositions\",", "        \"destruction_receipts\",", "        \"evidence_acquisition_intents\",", "        \"evidence_acquisition_results\",", "        \"capability_bindings\",", "    }", "", "", "# ------------------------------------------------------------------ manifest seal", "", "", "async def _terminal_manifest(ledger: AsyncSession, parents: Parents, **overrides: Any) -> uuid.UUID:", "    row = r.manifest_row(", "        parents, outcome=\"SKIPPED\", outcome_reason=\"none\", terminal_at=r.NOW, **overrides", "    )", "    await r.insert_row(ledger, \"sub_unit_manifests\", row)", "    return row[\"id\"]", "", "", "async def test_manifest_seal_accepts_empty_publication_set(", "    ledger: AsyncSession, parents: Parents", ") -> None:", "    \"\"\"A unit that published nothing seals with an empty array and registers.\"\"\"", "    table = r.table(\"sub_unit_manifests\")", "    await ledger.execute(", "        update(table)", "        .where(table.c.id == parents.manifest_id)", "        .values(", "            outcome=\"SKIPPED\", outcome_reason=\"none\", terminal_at=r.NOW, causal_publication_ids=[]", "        )", "    )", "    await ledger.execute(", "        update(table).where(table.c.id == parents.manifest_id).values(publications_registered=True)", "    )", "", "", "async def test_sealed_causal_publication_ids_cannot_change(", "    ledger: AsyncSession, parents: Parents", ") -> None:", "    manifest_id = await _terminal_manifest(ledger, parents, causal_publication_ids=[])", "    error = await _refused(", "        ledger, \"sub_unit_manifests\", manifest_id, {\"causal_publication_ids\": [uuid.uuid4()]}", "    )", "    assert \"causal_publication_ids is sealed on terminal manifest\" in str(error)", "", "", "async def test_publications_registered_cannot_reopen(", "    ledger: AsyncSession, parents: Parents", ") -> None:", "    manifest_id = await _terminal_manifest(", "        ledger, parents, causal_publication_ids=[], publications_registered=True", "    )", "    error = await _refused(", "        ledger, \"sub_unit_manifests\", manifest_id, {\"publications_registered\": False}", "    )", "    assert \"publications_registered cannot be reopened\" in str(error)", "", "", "async def test_publications_registered_needs_terminal(", "    ledger: AsyncSession, parents: Parents", ") -> None:", "    error = await _refused(", "        ledger, \"sub_unit_manifests\", parents.manifest_id, {\"publications_registered\": True}", "    )", "    assert error.constraint_name == \"ck_sub_unit_manifests_publications_registered\"", "", "", "async def test_outbox_relay_columns_move_and_body_does_not(", "    ledger: AsyncSession, parents: Parents", ") -> None:", "    \"\"\"Only relay lifecycle columns change; the publication payload is frozen.\"\"\"", "    row = r.outbox_row(parents)", "    await r.insert_row(ledger, \"ledger_outbox_entries\", row)", "    table = r.table(\"ledger_outbox_entries\")", "    await ledger.execute(", "        update(table)", "        .where(table.c.id == row[\"id\"])", "        .values(status=\"FAILED\", attempt_count=1, last_error=\"timeout\", next_attempt_at=r.LATER)", "    )", "    await ledger.execute(", "        update(table).where(table.c.id == row[\"id\"]).values(status=\"SENT\", dispatched_at=r.LATER)", "    )", "    error = await _refused(ledger, \"ledger_outbox_entries\", row[\"id\"], {\"payload\": {\"x\": 1}})", "    assert \"publication identity, body, causality and scope are immutable\" in str(error)", "", "", "# ------------------------------------------------------------------ scope binding", "", "", "async def _pre_scope_unit(", "    ledger: AsyncSession, parents: Parents, **overrides: Any", ") -> dict[str, Any]:", "    source_system_id = overrides.pop(\"source_system_id\", parents.source_system_id)", "    row = r.delivery_unit_row(", "        parents.client_id, source_system_id, **r.pre_scope_overrides(**overrides)", "    )", "    await r.insert_row(ledger, \"delivery_units\", row)", "    return row", "", "", "PENDING = {\"state\": \"PENDING_OPERATION_RESOLUTION\", \"landed_at\": r.NOW, **r.QUARANTINE_OBJECT}", "BIND = {", "    \"scope_kind\": \"OPERATION\",", "    \"operation_id\": OPERATION_ID,", "    \"scope_bound_at\": r.NOW,", "    \"state\": \"LANDED\",", "    \"landed_at\": r.NOW,", "    **r.QUARANTINE_OBJECT,", "}", "SCOPE_MESSAGE = \"scope identity is set-once\"", "PAYLOAD_MESSAGE = WRITE_ONCE_MESSAGE", "", "", "async def test_scope_fills_once_then_never_changes(ledger: AsyncSession, parents: Parents) -> None:", "    \"\"\"The one-time fill succeeds; every later typed-scope change, clear or payload change raises.\"\"\"", "    unit = await _pre_scope_unit(ledger, parents)", "    table = r.table(\"delivery_units\")", "    await ledger.execute(update(table).where(table.c.id == unit[\"id\"]).values(**BIND))", "    scope_key = await _current(ledger, \"delivery_units\", unit[\"id\"], \"scope_key\")", "    assert scope_key == f\"client:{parents.client_id}:operation:{OPERATION_ID}\"", "", "    for change, message in (", "        ({\"operation_id\": uuid.uuid4()}, SCOPE_MESSAGE),", "        ({\"scope_kind\": \"STANDING\", \"operation_id\": None}, SCOPE_MESSAGE),", "        ({\"scope_kind\": None, \"operation_id\": None}, SCOPE_MESSAGE),", "        ({\"scope_bound_at\": r.LATER}, SCOPE_MESSAGE),", "        ({\"scope_bound_at\": None}, SCOPE_MESSAGE),", "        ({\"payload_arrival_mode\": \"UPLOAD_INTENT\"}, PAYLOAD_MESSAGE),", "        ({\"payload_disposition\": \"TRANSIENT\"}, PAYLOAD_MESSAGE),", "    ):", "        error = await _refused(ledger, \"delivery_units\", unit[\"id\"], change)", "        assert message in str(error), (change, error)", "", "", "async def test_operation_cannot_be_added_to_bound_standing_unit(", "    ledger: AsyncSession, parents: Parents", ") -> None:", "    \"\"\"A STANDING delivery can never gain an operation_id.", "", "    v1.03's set-once guard only fences operation_id once it is non-null, so the", "    refusal here comes from ck_delivery_units_scope (STANDING requires a null", "    operation_id) rather than from the trigger.", "    \"\"\"", "    error = await _refused(", "        ledger, \"delivery_units\", parents.delivery_unit_id, {\"operation_id\": OPERATION_ID}", "    )", "    assert error.constraint_name == \"ck_delivery_units_scope\"", "", "", "PRE_SCOPE_STATES = {", "    \"RECEIVED\": {},", "    \"PENDING_OPERATION_RESOLUTION\": PENDING,", "    \"QUARANTINED\": {\"state\": \"QUARANTINED\", \"quarantine_reason_code\": \"OPERATION_UNRESOLVABLE\"},", "}", "", "", "def _children_of(unit_id: uuid.UUID) -> dict[str, Any]:", "    return {", "        \"evidence_acquisition_intents\": lambda p: r.intent_row(p, delivery_unit_id=unit_id),", "        \"scan_verdicts\": lambda p: r.scan_verdict_row(p, delivery_unit_id=unit_id),", "        \"sub_unit_manifests\": lambda p: r.manifest_row(p, delivery_unit_id=unit_id),", "        \"source_item_claims\": lambda p: r.claim_row(p, owning_delivery_unit_id=unit_id),", "        \"ledger_outbox_entries\": lambda p: r.outbox_row(p, delivery_unit_id=unit_id),", "        \"capability_bindings\": lambda p: r.capability_binding_row(p, delivery_unit_id=unit_id),", "        \"operator_dispositions\": lambda p: r.disposition_row(p, delivery_unit_id=unit_id),", "        \"destruction_receipts\": lambda p: r.destruction_receipt_row(p, delivery_unit_id=unit_id),", "    }", "", "", "@pytest.mark.parametrize(\"state\", sorted(PRE_SCOPE_STATES))", "async def test_unscoped_delivery_acquires_no_children(", "    ledger: AsyncSession, parents: Parents, state: str", ") -> None:", "    \"\"\"No child family can attach to an unscoped delivery: every edge needs its scope_key.\"\"\"", "    unit = await _pre_scope_unit(ledger, parents, **PRE_SCOPE_STATES[state])", "    for table_name, build in _children_of(unit[\"id\"]).items():", "        with pytest.raises(IntegrityError) as exc_info:", "            async with ledger.begin_nested():", "                await r.insert_row(ledger, table_name, build(parents))", "        error = r.pg_error(exc_info.value)", "        assert type(error).__name__ == \"ForeignKeyViolationError\", (table_name, error)", "", "", "async def test_unscoped_delivery_cannot_be_promoted(ledger: AsyncSession, parents: Parents) -> None:", "    unit = await _pre_scope_unit(ledger, parents, **PENDING)", "    error = await _refused(", "        ledger, \"delivery_units\", unit[\"id\"], {\"state\": \"ACCEPTED\", **r.EVIDENCE_OBJECT}", "    )", "    assert error.constraint_name == \"ck_delivery_units_scope_presence\"", "", "", "async def test_resolved_scope_received_unit_is_valid(", "    ledger: AsyncSession, parents: Parents", ") -> None:", "    \"\"\"An ordinary scoped RECEIVED unit (no external reference) inserts and takes children.\"\"\"", "    unit = r.delivery_unit_row(parents.client_id, parents.source_system_id)", "    await r.insert_row(ledger, \"delivery_units\", unit)", "    await r.insert_row(", "        ledger, \"scan_verdicts\", r.scan_verdict_row(parents, delivery_unit_id=unit[\"id\"])", "    )", "", "", "# ------------------------------------------------------------- absorbed duplicates", "", "", "async def _bound_original(ledger: AsyncSession, parents: Parents) -> dict[str, Any]:", "    \"\"\"A scope-bound delivery that a pending loser can be absorbed into.\"\"\"", "    row = r.delivery_unit_row(", "        parents.client_id,", "        parents.source_system_id,", "        external_namespace=\"ns\",", "        external_operation_key=f\"op-{uuid.uuid4().hex[:8]}\",", "        **BIND,", "    )", "    await r.insert_row(ledger, \"delivery_units\", row)", "    return row", "", "", "async def _pending_loser(", "    ledger: AsyncSession, parents: Parents, original: dict[str, Any], **overrides: Any", ") -> dict[str, Any]:", "    \"\"\"An unscoped pending delivery carrying the original's transport identity.\"\"\"", "    identity = {", "        \"unit_natural_key\": original[\"unit_natural_key\"],", "        \"unit_natural_key_kind\": original[\"unit_natural_key_kind\"],", "    }", "    return await _pre_scope_unit(ledger, parents, **{**PENDING, **identity, **overrides})", "", "", "ABSORB = {\"state\": \"ABSORBED_DUPLICATE\", \"terminal_at\": r.LATER}", "DUPLICATE_TARGET_MESSAGE = \"must be a scoped non-duplicate delivery\"", "ORIGIN_MESSAGE = \"absorption is reachable only from PENDING_OPERATION_RESOLUTION\"", "", "", "async def _absorb(ledger: AsyncSession, loser_id: uuid.UUID, original_id: uuid.UUID) -> None:", "    table = r.table(\"delivery_units\")", "    await ledger.execute(", "        update(table)", "        .where(table.c.id == loser_id)", "        .values(duplicate_of_delivery_unit_id=original_id, **ABSORB)", "    )", "", "", "async def test_pending_loser_is_absorbed_into_scoped_original(", "    ledger: AsyncSession, parents: Parents", ") -> None:", "    await ledger.execute(text(\"SET CONSTRAINTS ALL IMMEDIATE\"))", "    original = await _bound_original(ledger, parents)", "    loser = await _pending_loser(ledger, parents, original)", "    await _absorb(ledger, loser[\"id\"], original[\"id\"])", "    assert await _current(ledger, \"delivery_units\", loser[\"id\"], \"scope_key\") is None", "", "", "OTHER_SOURCE_SYSTEM = \"another source system of the same client\"", "", "", "@pytest.mark.parametrize(", "    \"mismatch\",", "    [", "        {\"unit_natural_key\": \"another-unit\"},", "        {\"unit_natural_key_kind\": \"MINTED\"},", "        {\"source_system_id\": OTHER_SOURCE_SYSTEM},", "    ],", "    ids=[\"unit_natural_key\", \"unit_natural_key_kind\", \"source_system_id\"],", ")", "async def test_absorption_requires_matching_transport_identity(", "    ledger: AsyncSession, parents: Parents, mismatch: dict[str, Any]", ") -> None:", "    await ledger.execute(text(\"SET CONSTRAINTS ALL IMMEDIATE\"))", "    if mismatch.get(\"source_system_id\") == OTHER_SOURCE_SYSTEM:", "        other = r.source_system_row(parents.client_id)", "        await r.insert_row(ledger, \"source_systems\", other)", "        mismatch = {\"source_system_id\": other[\"id\"]}", "    original = await _bound_original(ledger, parents)", "    loser = await _pending_loser(ledger, parents, original, **mismatch)", "    with pytest.raises(DBAPIError) as exc_info:", "        async with ledger.begin_nested():", "            await _absorb(ledger, loser[\"id\"], original[\"id\"])", "    assert DUPLICATE_TARGET_MESSAGE in str(r.pg_error(exc_info.value))", "", "", "async def test_absorption_into_an_original_scoped_at_receipt(", "    ledger: AsyncSession, parents: Parents", ") -> None:", "    \"\"\"v1.04: the target needs resolved scope, not scope_bound_at.", "", "    The seeded standing delivery was scoped at receipt, so its scope_bound_at is null.", "    \"\"\"", "    await ledger.execute(text(\"SET CONSTRAINTS ALL IMMEDIATE\"))", "    original = {", "        \"id\": parents.delivery_unit_id,", "        \"unit_natural_key\": await _current(", "            ledger, \"delivery_units\", parents.delivery_unit_id, \"unit_natural_key\"", "        ),", "        \"unit_natural_key_kind\": await _current(", "            ledger, \"delivery_units\", parents.delivery_unit_id, \"unit_natural_key_kind\"", "        ),", "    }", "    assert await _current(ledger, \"delivery_units\", original[\"id\"], \"scope_bound_at\") is None", "    loser = await _pending_loser(ledger, parents, original)", "    await _absorb(ledger, loser[\"id\"], original[\"id\"])", "    assert await _current(ledger, \"delivery_units\", loser[\"id\"], \"state\") == \"ABSORBED_DUPLICATE\"", "", "", "async def test_absorption_requires_a_scoped_original(", "    ledger: AsyncSession, parents: Parents", ") -> None:", "    \"\"\"A tombstone cannot point at a delivery that is itself still unscoped.\"\"\"", "    await ledger.execute(text(\"SET CONSTRAINTS ALL IMMEDIATE\"))", "    unscoped = await _pre_scope_unit(ledger, parents, **PENDING)", "    loser = await _pending_loser(ledger, parents, unscoped)", "    with pytest.raises(DBAPIError) as exc_info:", "        async with ledger.begin_nested():", "            await _absorb(ledger, loser[\"id\"], unscoped[\"id\"])", "    assert DUPLICATE_TARGET_MESSAGE in str(r.pg_error(exc_info.value))", "", "", "async def test_absorption_cannot_chain(ledger: AsyncSession, parents: Parents) -> None:", "    await ledger.execute(text(\"SET CONSTRAINTS ALL IMMEDIATE\"))", "    original = await _bound_original(ledger, parents)", "    first = await _pending_loser(ledger, parents, original)", "    await _absorb(ledger, first[\"id\"], original[\"id\"])", "    second = await _pending_loser(ledger, parents, original)", "    with pytest.raises(DBAPIError) as exc_info:", "        async with ledger.begin_nested():", "            await _absorb(ledger, second[\"id\"], first[\"id\"])", "    assert DUPLICATE_TARGET_MESSAGE in str(r.pg_error(exc_info.value))", "", "", "async def test_absorbed_duplicate_rejects_cross_client_original(", "    ledger: AsyncSession, parents: Parents", ") -> None:", "    \"\"\"A cross-client pointer is refused by the composite foreign key itself.\"\"\"", "    original = await _bound_original(ledger, parents)", "    other = await r.seed_parents(ledger, parents.client_id + 50_000)", "    loser = r.delivery_unit_row(", "        other.client_id, other.source_system_id, **r.pre_scope_overrides(**PENDING)", "    )", "    await r.insert_row(ledger, \"delivery_units\", loser)", "    error = await _refused(", "        ledger,", "        \"delivery_units\",", "        loser[\"id\"],", "        {\"duplicate_of_delivery_unit_id\": original[\"id\"], **ABSORB},", "    )", "    assert type(error).__name__ == \"ForeignKeyViolationError\"", "    assert error.constraint_name == \"delivery_units_duplicate_of_delivery_unit_id_client_id_fkey\"", "", "", "async def test_absorbed_duplicate_stays_childless(ledger: AsyncSession, parents: Parents) -> None:", "    \"\"\"Any child row for an ABSORBED_DUPLICATE unit raises.\"\"\"", "    await ledger.execute(text(\"SET CONSTRAINTS ALL IMMEDIATE\"))", "    original = await _bound_original(ledger, parents)", "    loser = await _pending_loser(ledger, parents, original)", "    await _absorb(ledger, loser[\"id\"], original[\"id\"])", "    for table_name, build in _children_of(loser[\"id\"]).items():", "        with pytest.raises(IntegrityError):", "            async with ledger.begin_nested():", "                await r.insert_row(ledger, table_name, build(parents))", "", "", "@pytest.mark.parametrize(\"column\", [\"source_system_id\", \"unit_natural_key_kind\"])", "async def test_absorbed_original_keeps_its_transport_identity(", "    ledger: AsyncSession, parents: Parents, column: str", ") -> None:", "    \"\"\"v1.05: the duplicate check runs only at absorption, so the original's match is fixed.\"\"\"", "    await ledger.execute(text(\"SET CONSTRAINTS ALL IMMEDIATE\"))", "    original = await _bound_original(ledger, parents)", "    loser = await _pending_loser(ledger, parents, original)", "    await _absorb(ledger, loser[\"id\"], original[\"id\"])", "    if column == \"source_system_id\":", "        other = r.source_system_row(parents.client_id)", "        await r.insert_row(ledger, \"source_systems\", other)", "        change = other[\"id\"]", "    else:", "        change = \"MINTED\"", "    error = await _refused(ledger, \"delivery_units\", original[\"id\"], {column: change})", "    assert WRITE_ONCE_MESSAGE in str(error), error", "", "", "async def test_claim_on_absorbed_duplicate_hits_the_childless_trigger(", "    ledger: AsyncSession, parents: Parents", ") -> None:", "    \"\"\"The claim's owning-delivery FK carries no scope, so the trigger is what refuses it.", "", "    The claim and its lineage use the tombstone's dataset, so both foreign keys pass.", "    \"\"\"", "    await ledger.execute(text(\"SET CONSTRAINTS ALL IMMEDIATE\"))", "    original = await _bound_original(ledger, parents)", "    loser = await _pending_loser(ledger, parents, original)", "    await _absorb(ledger, loser[\"id\"], original[\"id\"])", "    lineage = r.lineage_row(parents, dataset_id=loser[\"dataset_id\"])", "    await r.insert_row(ledger, \"source_record_lineages\", lineage)", "    claim = r.claim_row(", "        parents,", "        owning_delivery_unit_id=loser[\"id\"],", "        dataset_id=loser[\"dataset_id\"],", "        source_record_lineage_id=lineage[\"id\"],", "    )", "    with pytest.raises(IntegrityError) as exc_info:", "        async with ledger.begin_nested():", "            await r.insert_row(ledger, \"source_item_claims\", claim)", "    assert \"ABSORBED_DUPLICATE and must stay childless\" in str(r.pg_error(exc_info.value))", "", "", "async def test_scoped_unit_cannot_become_absorbed(ledger: AsyncSession, parents: Parents) -> None:", "    \"\"\"A delivery that holds scope can never be tombstoned.", "", "    It is not pending, so trg_delivery_units_absorption_origin refuses it before", "    the set-once trigger (which also refuses clearing scope) runs.", "    \"\"\"", "    await ledger.execute(text(\"SET CONSTRAINTS ALL IMMEDIATE\"))", "    original = await _bound_original(ledger, parents)", "    error = await _refused(", "        ledger,", "        \"delivery_units\",", "        parents.delivery_unit_id,", "        {\"duplicate_of_delivery_unit_id\": original[\"id\"], \"scope_kind\": None, **ABSORB},", "    )", "    assert ORIGIN_MESSAGE in str(error)", "", "", "@pytest.mark.parametrize(\"state\", [\"RECEIVED\", \"QUARANTINED\"])", "async def test_absorption_only_from_pending(", "    ledger: AsyncSession, parents: Parents, state: str", ") -> None:", "    \"\"\"trg_delivery_units_absorption_origin: an unscoped non-pending unit cannot be absorbed.\"\"\"", "    await ledger.execute(text(\"SET CONSTRAINTS ALL IMMEDIATE\"))", "    original = await _bound_original(ledger, parents)", "    unit = await _pre_scope_unit(", "        ledger,", "        parents,", "        unit_natural_key=original[\"unit_natural_key\"],", "        unit_natural_key_kind=original[\"unit_natural_key_kind\"],", "        **PRE_SCOPE_STATES[state],", "    )", "    with pytest.raises(DBAPIError) as exc_info:", "        async with ledger.begin_nested():", "            await _absorb(ledger, unit[\"id\"], original[\"id\"])", "    error = str(r.pg_error(exc_info.value))", "    assert ORIGIN_MESSAGE in error and f\"from {state} to ABSORBED_DUPLICATE\" in error", "", "", "async def test_absorbed_duplicate_cannot_be_inserted(", "    ledger: AsyncSession, parents: Parents", ") -> None:", "    \"\"\"A row can only become a tombstone by transition, never be born as one.\"\"\"", "    original = await _bound_original(ledger, parents)", "    row = r.delivery_unit_row(", "        parents.client_id,", "        parents.source_system_id,", "        unit_natural_key=original[\"unit_natural_key\"],", "        unit_natural_key_kind=original[\"unit_natural_key_kind\"],", "        duplicate_of_delivery_unit_id=original[\"id\"],", "        **{**r.pre_scope_overrides(**PENDING), **ABSORB},", "    )", "    with pytest.raises(DBAPIError) as exc_info:", "        async with ledger.begin_nested():", "            await r.insert_row(ledger, \"delivery_units\", row)", "    assert \"cannot be ABSORBED_DUPLICATE at insert\" in str(r.pg_error(exc_info.value))", "", "", "# ------------------------------------------------------------- dataset and dereference", "", "", "async def test_claim_dataset_must_match_lineage(ledger: AsyncSession, parents: Parents) -> None:", "    \"\"\"Enforced by the lineage foreign key, which includes dataset_id.\"\"\"", "    other_unit = r.delivery_unit_row(parents.client_id, parents.source_system_id)", "    await r.insert_row(ledger, \"delivery_units\", other_unit)", "    claim = r.claim_row(", "        parents, owning_delivery_unit_id=other_unit[\"id\"], dataset_id=other_unit[\"dataset_id\"]", "    )", "    with pytest.raises(IntegrityError) as exc_info:", "        async with ledger.begin_nested():", "            await r.insert_row(ledger, \"source_item_claims\", claim)", "    error = r.pg_error(exc_info.value)", "    assert type(error).__name__ == \"ForeignKeyViolationError\"", "    assert (", "        error.constraint_name == \"source_item_claims_source_record_lineage_id_dataset_id_sco_fkey\"", "    )", "", "", "async def test_delivery_binding_facts_are_stored(ledger: AsyncSession, parents: Parents) -> None:", "    \"\"\"Every delivery stores its effective disposition and dataset binding facts (NOT NULL).\"\"\"", "    nullable = (", "        await ledger.execute(", "            text(", "                \"SELECT column_name FROM information_schema.columns WHERE table_schema = 'ingest_ledger' \"", "                \"AND table_name = 'delivery_units' AND is_nullable = 'YES' AND column_name = ANY(:c)\"", "            ),", "            {", "                \"c\": [", "                    \"payload_disposition\",", "                    \"payload_arrival_mode\",", "                    \"source_dataset_binding_id\",", "                    \"source_dataset_binding_version\",", "                    \"dataset_id\",", "                    \"dataset_catalog_version\",", "                ]", "            },", "        )", "    ).scalars()", "    assert list(nullable) == []", "", "", "async def test_prohibited_dereference_creates_no_acquisition_rows(", "    ledger: AsyncSession, parents: Parents", ") -> None:", "    with pytest.raises(IntegrityError) as exc_info:", "        async with ledger.begin_nested():", "            await r.insert_row(", "                ledger,", "                \"evidence_acquisition_intents\",", "                r.intent_row(parents, dereference_policy_applied=\"PROHIBITED\"),", "            )", "    assert r.pg_error(exc_info.value).constraint_name == \"ck_evidence_acquisition_intents_policy\"", "", "", "async def test_unfetched_external_reference_has_no_scan_verdict(", "    ledger: AsyncSession, parents: Parents", ") -> None:", "    \"\"\"A pending external reference holds no Polaris bytes, so no verdict can attach to it.\"\"\"", "    unit = await _pre_scope_unit(", "        ledger,", "        parents,", "        payload_arrival_mode=\"NO_POLARIS_BYTES\",", "        payload_disposition=\"EXTERNAL_REFERENCE\",", "        external_reference_uri=\"s3://customer/object\",", "        state=\"PENDING_OPERATION_RESOLUTION\",", "    )", "    with pytest.raises(IntegrityError):", "        async with ledger.begin_nested():", "            await r.insert_row(", "                ledger, \"scan_verdicts\", r.scan_verdict_row(parents, delivery_unit_id=unit[\"id\"])", "            )"], "blocks": [{"start": 1, "end": 457, "label": "Imports and module setup"}, {"start": 458, "end": 475, "label": "def _different_value"}, {"start": 476, "end": 486, "label": "def _refused"}, {"start": 487, "end": 495, "label": "def _current"}, {"start": 496, "end": 522, "label": "def test_guarded_column_cannot_change"}, {"start": 523, "end": 554, "label": "def test_guard_specification_covers_the_ticket_rules"}, {"start": 555, "end": 573, "label": "def test_unguarded_update_still_succeeds"}, {"start": 574, "end": 594, "label": "def test_effective_latency_classes_stay_mutable"}, {"start": 595, "end": 606, "label": "def _append_only_row"}, {"start": 607, "end": 631, "label": "def test_append_only_tables_reject_update_and_delete"}, {"start": 632, "end": 645, "label": "def test_append_only_set_is_the_six_named_tables"}, {"start": 646, "end": 653, "label": "def _terminal_manifest"}, {"start": 654, "end": 670, "label": "def test_manifest_seal_accepts_empty_publication_set"}, {"start": 671, "end": 680, "label": "def test_sealed_causal_publication_ids_cannot_change"}, {"start": 681, "end": 692, "label": "def test_publications_registered_cannot_reopen"}, {"start": 693, "end": 701, "label": "def test_publications_registered_needs_terminal"}, {"start": 702, "end": 723, "label": "def test_outbox_relay_columns_move_and_body_does_not"}, {"start": 724, "end": 747, "label": "def _pre_scope_unit"}, {"start": 748, "end": 768, "label": "def test_scope_fills_once_then_never_changes"}, {"start": 769, "end": 790, "label": "def test_operation_cannot_be_added_to_bound_standing_unit"}, {"start": 791, "end": 803, "label": "def _children_of"}, {"start": 804, "end": 817, "label": "def test_unscoped_delivery_acquires_no_children"}, {"start": 818, "end": 825, "label": "def test_unscoped_delivery_cannot_be_promoted"}, {"start": 826, "end": 839, "label": "def test_resolved_scope_received_unit_is_valid"}, {"start": 840, "end": 852, "label": "def _bound_original"}, {"start": 853, "end": 868, "label": "def _pending_loser"}, {"start": 869, "end": 877, "label": "def _absorb"}, {"start": 878, "end": 890, "label": "def test_pending_loser_is_absorbed_into_scoped_original"}, {"start": 891, "end": 915, "label": "def test_absorption_requires_matching_transport_identity"}, {"start": 916, "end": 938, "label": "def test_absorption_into_an_original_scoped_at_receipt"}, {"start": 939, "end": 951, "label": "def test_absorption_requires_a_scoped_original"}, {"start": 952, "end": 963, "label": "def test_absorption_cannot_chain"}, {"start": 964, "end": 983, "label": "def test_absorbed_duplicate_rejects_cross_client_original"}, {"start": 984, "end": 995, "label": "def test_absorbed_duplicate_stays_childless"}, {"start": 996, "end": 1014, "label": "def test_absorbed_original_keeps_its_transport_identity"}, {"start": 1015, "end": 1039, "label": "def test_claim_on_absorbed_duplicate_hits_the_childless_trigger"}, {"start": 1040, "end": 1056, "label": "def test_scoped_unit_cannot_become_absorbed"}, {"start": 1057, "end": 1077, "label": "def test_absorption_only_from_pending"}, {"start": 1078, "end": 1099, "label": "def test_absorbed_duplicate_cannot_be_inserted"}, {"start": 1100, "end": 1116, "label": "def test_claim_dataset_must_match_lineage"}, {"start": 1117, "end": 1139, "label": "def test_delivery_binding_facts_are_stored"}, {"start": 1140, "end": 1152, "label": "def test_prohibited_dereference_creates_no_acquisition_rows"}, {"start": 1153, "end": 1169, "label": "def test_unfetched_external_reference_has_no_scan_verdict"}], "lineCount": 1169, "sha256": "59b4c53d4195f8e91c4b9b5a4dea0c55de1f19a3a9f38d6477e18d05e1db840c", "endsWithNewline": true});
